//! 剪贴板监听线程（macOS 与 Windows 共用，平台差异封装在 `platform::pasteboard` 中）。
//!
//! 流程与 PasteNow 日志中看到的一致：
//! 定时器触发 → 比较 changeCount（“On auto check pasteboard: count change from … to …”）→
//! 检查 Concealed/Transient/AutoGenerated 标记与排除规则 → 读取全部类型 →
//! 计算指纹，已存在则更新（“PasteItem with checksum … is already exists, just update it”）→
//! 图片生成缩略图 → 写入数据库。

use std::sync::atomic::Ordering;
use std::sync::Arc;
use std::thread::JoinHandle;
use std::time::{Duration, Instant};

use anyhow::Result;
use devtools_clipboard::store::now_ms;
use devtools_clipboard::{thumbnail, uti, Capture, RecordOutcome, Store};

use crate::platform::pasteboard::Pasteboard;
use crate::platform::workspace;
use crate::shared::Shared;

/// 按保留时长与条数清理历史的间隔。
const PRUNE_INTERVAL: Duration = Duration::from_secs(30 * 60);

/// 启动监听线程。`store` 由调用方在主线程打开（顺带完成数据库迁移），监听线程独占这个连接。
pub fn spawn(shared: Arc<Shared>, store: Store, pasteboard_name: Option<String>) -> JoinHandle<()> {
    std::thread::Builder::new()
        .name("clipboard-monitor".into())
        .spawn(move || run(&shared, store, pasteboard_name.as_deref()))
        .expect("无法创建监听线程")
}

/// 监听循环：剪贴板序号变化时读取并记录，定期清理过期的历史。
fn run(shared: &Shared, mut store: Store, pasteboard_name: Option<&str>) {
    let pasteboard = pasteboard_name.map_or_else(Pasteboard::general, Pasteboard::named);
    // 启动时也记录一次当前剪贴板内容（若已存在只会更新时间）。
    let mut last_count: Option<isize> = None;
    let mut last_prune: Option<Instant> = None;
    tracing::info!(
        "开始监听剪贴板，间隔 {} ms",
        shared.poll_interval_ms.load(Ordering::Relaxed)
    );

    while !shared.stop.load(Ordering::Relaxed) {
        // 记录用户当前所在的程序：从托盘弹出面板时前台是任务栏，用它作为粘贴目标。
        workspace::remember_foreground();

        if last_prune.is_none_or(|at| at.elapsed() >= PRUNE_INTERVAL) {
            prune(shared, &mut store);
            last_prune = Some(Instant::now());
        }

        let count = pasteboard.change_count();
        if shared.writing.load(Ordering::SeqCst) {
            // 本应用正在写剪贴板，等写完再看。
        } else if last_count != Some(count) {
            last_count = Some(count);
            let ours = count == shared.ignore_change_count.load(Ordering::Relaxed);
            if !ours && !shared.paused.load(Ordering::Relaxed) {
                match capture_once(shared, &pasteboard, &mut store) {
                    Ok(Some(outcome)) => {
                        tracing::debug!("记录剪贴板 #{} (新建: {})", outcome.id, outcome.inserted);
                        shared.bump_revision();
                    }
                    Ok(None) => {}
                    Err(err) => tracing::warn!("记录剪贴板失败：{err:#}"),
                }
            }
        }

        let interval = shared
            .poll_interval_ms
            .load(Ordering::Relaxed)
            .clamp(50, 5_000);
        std::thread::sleep(Duration::from_millis(interval));
    }
}

/// 读取一次剪贴板并按规则记录；被规则跳过时返回 `None`。
fn capture_once(
    shared: &Shared,
    pasteboard: &Pasteboard,
    store: &mut Store,
) -> Result<Option<RecordOutcome>> {
    let rules = shared.config().rules;
    let source = workspace::frontmost_app();
    // 先只看类型列表：被标记为密码等隐私内容时，连数据都不读取。
    if let Err(reason) = rules.check_markers(&pasteboard.types(), &source) {
        tracing::debug!("跳过：{reason}");
        return Ok(None);
    }
    let snapshot = pasteboard.read();
    let analysis = uti::analyze(&snapshot);
    if let Err(reason) = rules.check(&snapshot, &analysis, &source) {
        tracing::debug!("跳过：{reason}");
        return Ok(None);
    }
    let thumbnail = analysis
        .image_uti
        .and_then(|ty| snapshot.first(ty))
        .and_then(|bytes| match thumbnail::make(bytes) {
            Ok(thumb) => Some(thumb),
            Err(err) => {
                tracing::debug!("生成缩略图失败：{err:#}");
                None
            }
        });
    let capture = Capture {
        snapshot,
        source,
        captured_at_ms: now_ms(),
    };
    store
        .record(&capture, &analysis, thumbnail.as_ref())
        .map(Some)
}

/// 按当前设置清理过期或超出条数的历史，有删除时通知 UI 刷新。
fn prune(shared: &Shared, store: &mut Store) {
    let config = shared.config();
    match store.prune(now_ms(), config.retention_ms, config.max_items) {
        Ok(0) => {}
        Ok(removed) => {
            tracing::info!("清理过期历史 {removed} 条");
            shared.bump_revision();
        }
        Err(err) => tracing::warn!("清理历史失败：{err:#}"),
    }
}

// 端到端测试依赖 macOS 的私有命名剪贴板（不影响系统剪贴板）；Windows 没有对应机制。
#[cfg(all(test, target_os = "macos"))]
mod tests {
    use super::*;
    use crate::settings::Settings;
    use devtools_clipboard::{ItemQuery, Representation, Snapshot};

    fn wait_for(mut condition: impl FnMut() -> bool) -> bool {
        let deadline = Instant::now() + Duration::from_secs(5);
        while Instant::now() < deadline {
            if condition() {
                return true;
            }
            std::thread::sleep(Duration::from_millis(20));
        }
        false
    }

    /// 端到端：在私有剪贴板上写入数据，验证监听线程的记录、去重、隐私过滤和“自己写入”跳过。
    #[test]
    fn monitor_records_dedups_and_filters_on_private_pasteboard() {
        let dir = tempfile::tempdir().unwrap();
        let settings = Settings {
            poll_interval_ms: 50,
            ..Settings::default()
        };
        let shared = Shared::new(&settings);
        let pasteboard = Pasteboard::unique();
        let name = pasteboard.name();
        let handle = spawn(shared.clone(), Store::open(dir.path()).unwrap(), Some(name));
        let store = Store::open(dir.path()).unwrap();
        let items = || store.items(&ItemQuery::default()).unwrap();
        let revision = || shared.revision.load(Ordering::Relaxed);

        pasteboard.write(&Snapshot::from_text("first copy"));
        assert!(wait_for(|| items().len() == 1), "应记录第一条");

        let mut secret = Snapshot::from_text("p@ssw0rd");
        secret.items[0].push(Representation::new(uti::CONCEALED, Vec::new()));
        pasteboard.write(&secret);
        pasteboard.write(&Snapshot::from_text("first copy"));
        assert!(
            wait_for(|| items().first().is_some_and(|item| item.copy_count == 2)),
            "重复内容应只更新次数"
        );
        assert_eq!(items().len(), 1, "Concealed 内容不应被记录");

        // 模拟粘贴时由本应用写入剪贴板：监听线程应跳过。
        let before = revision();
        shared.write_pasteboard(|| pasteboard.write(&Snapshot::from_text("written by us")));
        std::thread::sleep(Duration::from_millis(300));
        assert_eq!(revision(), before);
        assert_eq!(items().len(), 1);

        shared.paused.store(true, Ordering::Relaxed);
        pasteboard.write(&Snapshot::from_text("while paused"));
        std::thread::sleep(Duration::from_millis(300));
        assert_eq!(items().len(), 1, "暂停时不记录");

        shared.stop.store(true, Ordering::Relaxed);
        handle.join().unwrap();
        pasteboard.release();
    }
}
